function knightDialer(n) {
  const MOD = 1000000007;
  const moves = [[4, 6], [6, 8], [7, 9], [4, 8], [0, 3, 9], [], [0, 1, 7], [2, 6], [1, 3], [2, 4]];
  let counts = new Array(10).fill(1);

  for (let step = 1; step < n; step++) {
    const next = new Array(10).fill(0);
    for (let digit = 0; digit < 10; digit++) {
      for (const target of moves[digit]) {
        next[target] = (next[target] + counts[digit]) % MOD;
      }
    }
    counts = next;
  }

  let total = 0;
  for (const count of counts) {
    total = (total + count) % MOD;
  }
  return total;
}

