function knightDialer(n) {
  // Work on the keypad's geometry directly: -1 marks the * and # keys.
  const pad = [[1, 2, 3], [4, 5, 6], [7, 8, 9], [-1, 0, -1]];
  const jumps = [[1, 2], [2, 1], [-1, 2], [-2, 1], [1, -2], [2, -1], [-1, -2], [-2, -1]];
  let ways = pad.map(row => row.map(key => (key >= 0 ? 1 : 0)));
  for (let length = 2; length <= n; length++) {
    ways = pad.map((row, r) => row.map((key, c) => {
      if (key < 0) return 0;
      let sum = 0;
      for (const [dr, dc] of jumps) {
        const rr = r + dr, cc = c + dc;
        if (rr >= 0 && rr < 4 && cc >= 0 && cc < 3 && pad[rr][cc] >= 0) sum = (sum + ways[rr][cc]) % 1000000007;
      }
      return sum;
    }));
  }
  let total = 0;
  for (const row of ways) for (const w of row) total = (total + w) % 1000000007;
  return total;
}

